func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestAddTable(t *testing.T) {
	cases := []struct {
		name   string
		a      int
		b      int
		expect int
	}{
		{name: "positive", a: 2, b: 3, expect: 5},
		{name: "negative", a: -2, b: -3, expect: -5},
		{name: "zero", a: 0, b: 0, expect: 0},
		{name: "mixed", a: 5, b: -3, expect: 2},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := add(tc.a, tc.b); got != tc.expect {
				t.Fatalf("add(%d, %d) = %d, want %d", tc.a, tc.b, got, tc.expect)
			}
		})
	}
}

